package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamKarmaBank {
  private const val T = "කර්මය, පුනර්භවය හා චිත්ත සංවර්ධනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බුදුරජාණන් වහන්සේ 'චේතනාහං භික්ඛවේ කම්මං වදාමි' යනුවෙන් කර්මය ලෙස හැඳින්වූයේ කුමක්ද?", "චේතනාව", "ශාරීරික ශක්තිය", "බාහිර පෙනුම", "පරිසරය", "සිතාමතා කරන ක්‍රියාව හෙවත් චේතනාව කර්මය වන බව වදාළහ."),
    q("කර්ම සිදුවන ප්‍රධාන ද්වාර තුන (ත්‍රිද්වාර) මොනවාද?", "කය, වචනය, සිත", "ඇස, කන, නාසය", "දාන, ශීල, භාවනා", "ලෝභ, ද්වේෂ, මෝහ", "කාය කර්ම, වචී කර්ම හා මනෝ කර්ම ලෙස කර්ම සිදු වේ."),
    q("කර්මයේ විපාක දෙන කාලය අනුව ඒවා බෙදා ඇති කොටස් ගණන කීයද?", "සතරකි", "තුනකි", "පහකි", "දෙකකි", "දිට්ඨධම්මවේදනීය, උපපජ්ජවේදනීය, අපරාපරියවේදනීය හා අහෝසි කර්ම යනු සතරයි."),
    q("මේ ආත්මයේදීම විපාක ලැබෙන කර්මය හඳුන්වන්නේ කුමන නමින්ද?", "දිට්ඨධම්මවේදනීය කර්මය", "උපපජ්ජවේදනීය කර්මය", "අපරාපරියවේදනීය කර්මය", "අහෝසි කර්මය", "පළමු ජවන් සිතේ චේතනාව අනුව මෙලොවදීම විපාක දෙන කර්මයයි."),
    q("මෙලොවින් පසු ඊළඟ භවයේදීම විපාක දෙන කර්මය කුමක්ද?", "උපපජ්ජවේදනීය කර්මය", "දිට්ඨධම්මවේදනීය කර්මය", "අපරාපරියවේදනීය කර්මය", "අහෝසි කර්මය", "සත්වන ජවන් සිතේ බලයෙන් අනතුරු භවයේදී විපාක දේ."),
    q("සසර පුරා නිවන් දකින තුරුම ඉඩ ලැබුණු ඕනෑම භවයක විපාක දෙන කර්මය කුමක්ද?", "අපරාපරියවේදනීය කර්මය", "දිට්ඨධම්මවේදනීය කර්මය", "උපපජ්ජවේදනීය කර්මය", "ජනක කර්මය", "මැද ජවන් සිත්වල කර්ම ශක්තිය සසර පුරා අවස්ථා ලැබෙන විට විපාක දේ."),
    q("විපාක දීමට අවස්ථාවක් නොලැබීම නිසා අවලංගු වී යන කර්මය කුමක්ද?", "අහෝසි කර්මය", "ගරුක කර්මය", "ආසන්න කර්මය", "ආචිණ්ණ කර්මය", "රහත්ව පිරිනිවන් පෑමේදී ද ඉතිරි කර්ම අහෝසි කර්ම බවට පත්වේ."),
    q("කෘත්‍ය අනුව කර්ම වර්ගීකරණයේදී සත්වයාගේ ප්‍රතිසන්ධිය ලබා දෙන කර්මය කුමක්ද?", "ජනක කර්මය", "උපත්ථම්භක කර්මය", "උපපීළක කර්මය", "උපඝාතක කර්මය", "නව භවයක උපත සිදු කරන්නේ ජනක කර්මය මගිනි."),
    q("ජනක කර්මයෙන් ලැබුණු භවය තවදුරටත් පවත්වා ගෙන යාමට රුකුල් දෙන කර්මය කුමක්ද?", "උපත්ථම්භක කර්මය", "උපපීළක කර්මය", "උපඝාතක කර්මය", "ගරුක කර්මය", "ලැබූ භවයේ සැප හෝ දුක් වැඩි දියුණු කරමින් ආධාර කරයි."),
    q("ජනක කර්මයෙන් ලැබුණු සැප හෝ දුක් විපාකවලට බාධා කරමින් පීඩා ගෙන දෙන කර්මය කුමක්ද?", "උපපීළක කර්මය", "උපත්ථම්භක කර්මය", "උපඝාතක කර්මය", "ජනක කර්මය", "සැප විපාක අඩු කිරීමට හෝ දුක් විපාක අඩු කිරීමට උපපීළක කර්මය බලපායි."),
    q("පෙර කළ ප්‍රබල ජනක කර්මයක විපාක සම්පූර්ණයෙන්ම විනාශ කර දමන කර්මය කුමක්ද?", "උපඝාතක කර්මය", "උපපීළක කර්මය", "උපත්ථම්භක කර්මය", "කටත්තා කර්මය", "වෙනත් බලවත් කර්මයකින් පෙර කර්ම විපාකය සිඳ දැමීම උපඝාතක කර්මයයි."),
    q("විපාක දීමේ පිළිවෙළ (පාකදාන පර්යාය) අනුව ප්‍රථමයෙන්ම විපාක දෙන ප්‍රබලතම කර්මය කුමක්ද?", "ගරුක කර්මය", "ආසන්න කර්මය", "ආචිණ්ණ කර්මය", "කටත්තා කර්මය", "පංච ආනන්තරිය පාප කර්ම හා ධ්‍යාන කුසල් ගරුක කර්ම වේ."),
    q("පංච ආනන්තරිය පාප කර්ම අතරට අයත් නොවන ක්‍රියාව කුමක්ද?", "සොරකම් කිරීම", "මව මැරීම", "පියා මැරීම", "සංඝ භේදය", "මව, පියා, රහතුන් මැරීම, බුදු සිරුරේ ලේ සෙලවීම, සංඝ භේදය ආනන්තරිය කර්ම පහයි."),
    q("මරණාසන්න මොහොතේ සිහිපත් වන හෝ කරන කර්මය හඳුන්වන්නේ කුමන නමින්ද?", "ආසන්න කර්මය", "ගරුක කර්මය", "ආචිණ්ණ කර්මය", "කටත්තා කර්මය", "මරණාසන්නයේදී පහළ වන සිතුවිල්ල ඊළඟ භවයට බලපායි."),
    q("නිතර නිතර පුරුද්දක් ලෙස කරනු ලබන කුසල් හෝ අකුසල් කර්ම හඳුන්වන්නේ කුමන නමින්ද?", "ආචිණ්ණ කර්මය", "ආසන්න කර්මය", "කටත්තා කර්මය", "ගරුක කර්මය", "පුරුද්දක් ලෙස දිනපතා කරන ක්‍රියා ආචිණ්ණ කර්ම වේ."),
    q("විශේෂ උනන්දුවකින් තොරව අහම්බෙන් හෝ අමතක වන ආකාරයෙන් කළ කර්මය කුමක්ද?", "කටත්තා කර්මය", "ගරුක කර්මය", "ආසන්න කර්මය", "ආචිණ්ණ කර්මය", "ඉහත කර්ම තුන නොමැති විට කටත්තා කර්මය විපාක දෙයි."),
    q("කයින් සිදුවන අකුසල් කර්ම තුන මොනවාද?", "ප්‍රාණඝාතය, අදත්තාදානය, කාමමිථ්‍යාචාරය", "මුසාවාද, පිසුණාවාචා, ඵරුසාවාචා", "අභිජ්ඣා, ව්‍යාපාද, මිච්ඡාදිට්ඨි", "සුරාපානය, සූදුව, අලසකම", "දස අකුසල්වල මුල් තුන කාය කර්ම වේ."),
    q("වචනයෙන් සිදුවන අකුසල් හතර අතර 'පිසුණාවාචා' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "කේලාම් කීම", "බොරු කීම", "පරුෂ වචන කීම", "හිස් වචන කීම", "දෙදෙනෙකු බිඳවන කේලාම් කීම පිසුණාවාචා නම් වේ."),
    q("වචනයෙන් සිදුවන අකුසලයක් වන 'සම්ඵප්ප්‍රලාප' යනු කුමක්ද?", "හිස් ප්‍රලාප දෙඩීම", "සත්‍යය කතා කිරීම", "ප්‍රිය වචන කීම", "බණ දේශනා කිරීම", "මෙලොව පරලොව දෙකටම අර්ථයක් නැති හිස් වචන කීම සම්ඵප්ප්‍රලාපයයි."),
    q("සිතින් සිදුවන මනෝ කර්ම තුන මොනවාද?", "අභිජ්ඣා, ව්‍යාපාද, මිච්ඡාදිට්ඨි", "ප්‍රාණඝාත, අදත්තාදාන, කාමමිථ්‍යාචාර", "මුසාවාද, පිසුණාවාචා, ඵරුසාවාචා", "දාන, සීල, භාවනා", "අනුන්ගේ දේට ලෝභ කිරීම, ක්‍රෝධ කිරීම හා වැරදි දෘෂ්ටිය මනෝ අකුසල් වේ."),
    q("අනුන්ගේ සම්පත් තමා සතු වේවා යැයි සිතින් සිතීම කුමන අකුසලයද?", "අභිජ්ඣා (දැඩි ලෝභය)", "ව්‍යාපාදය", "මිච්ඡාදිට්ඨිය", "කාමමිථ්‍යාචාරය", "දැඩි විෂම ලෝභය අභිජ්ඣා නම් මනෝ අකුසලයයි."),
    q("සියලු සතුන් විනාශ වේවා යැයි සිතන ද්වේෂ සහගත චේතනාව කුමක්ද?", "ව්‍යාපාදය", "අභිජ්ඣාව", "මිච්ඡාදිට්ඨිය", "මුසාවාදය", "කෝපයෙන් හා වෛරයෙන් අන් අයගේ විනාශය පැතීම ව්‍යාපාදයයි."),
    q("දස පුණ්‍ය ක්‍රියා අතරින් 'අපචායන' යන්නෙහි අර්ථය කුමක්ද?", "වැඩිහිටියන්ට හා ගුණවතුන්ට ගරු කිරීම", "ගිලනුන්ට උපස්ථාන කිරීම", "පින් අනුමෝදන් කිරීම", "ධර්මය ශ්‍රවණය කිරීම", "දාන, ශීල, භාවනා ආදී දස පුණ්‍ය ක්‍රියාවල සිව්වැන්න අපචායනයයි."),
    q("රෝගීන්ට හා දෙමාපියන්ට වතාවත් ඉටු කිරීම දස පුණ්‍ය ක්‍රියාවල හඳුන්වන්නේ කෙසේද?", "වෙය්‍යාවච්ච", "පත්තිදාන", "පත්තානුමෝදනා", "දිට්ඨිජුකම්ම", "වැඩිහිටියන්ට, සංඝයාට හා රෝගීන්ට උපස්ථාන කිරීම වෙය්‍යාවච්චයයි."),
    q("තමා කළ පින් අන් අයට ද අනුමෝදන් කිරීම කුමන පුණ්‍ය ක්‍රියාවද?", "පත්තිදාන (පින් දීම)", "පත්තානුමෝදනා", "ධම්මදේසනා", "ධම්මස්සවන", "මියගිය ඥාතීන්ට හා සියලු සතුන්ට පින් අනුමෝදන් කිරීම පත්තිදානයයි."),
    q("අනුන් කළ පින් දැක සතුටින් අනුමෝදන් වීම කුමන පුණ්‍ය ක්‍රියාවද?", "පත්තානුමෝදනා", "පත්තිදාන", "අපචායන", "වෙය්‍යාවච්ච", "මුදිතාවෙන් යුතුව පින් අනුමෝදන් වීමෙන් තමාටද පින් රැස් වේ."),
    q("තමන්ගේ දෘෂ්ටිය හෙවත් දැකීම ඍජු කර ගැනීම දස පුණ්‍ය ක්‍රියාවල හඳුන්වන්නේ කෙසේද?", "දිට්ඨිජුකම්ම", "ධම්මස්සවන", "භාවනා", "ශීල", "කර්ම ඵල ඇතැයි සම්මා දිට්ඨියේ පිහිටීම දිට්ඨිජුකම්ම නම් වේ."),
    q("සත්වයන් අතර ආයුෂ අඩු බව, රෝගාබාධ බහුල බව ආදිය කර්මය අනුව විග්‍රහ වන සූත්‍රය කුමක්ද?", "චූලකම්මවිභංග සූත්‍රය", "මහාමංගල සූත්‍රය", "සිඟාලෝවාද සූත්‍රය", "වසල සූත්‍රය", "සුභ මාණවකයා ඇසූ ප්‍රශ්නවලට බුදුරදුන් කර්ම විපාක විස්තර කළහ."),
    q("සුභ මාණවකයාට බුදුරදුන් දෙසූ පරිදි කෙනෙකු අල්පායුෂ්ක වීමට හේතු වන පාප කර්මය කුමක්ද?", "ප්‍රාණඝාතය", "මසුරුකම", "ඊර්ෂ්‍යාව", "අතිමානය", "සතුන් මැරීම අල්පායුෂ්ක වීමටත් අවිහිංසාව දීර්ඝායුෂ්ක වීමටත් හේතු වේ."),
    q("කෙනෙකු බොහෝ රෝග පීඩාවලින් පෙළීමට හේතු වන අකුසල කර්මය කුමක්ද?", "සතුන්ට හා අන් අයට හිංසා කිරීම", "දන් නොදීම", "කේලාම් කීම", "සුරාපානය", "කරුණාවෙන් අන් අයට පිහිට වීම නිරෝගී බවට හේතු වේ."),
    q("මසුරුකමින් යුතුව දන් නොදී සිටීමෙන් මතු භවයේ ඇතිවන විපාකය කුමක්ද?", "දිළිඳු වීම (අල්ප භෝග ඇති වීම)", "රෝගී වීම", "අල්පායුෂ්ක වීම", "අවලස්සන වීම", "දන් දීමෙන් මහා භෝග සම්පත් ලැබෙන බව චූලකම්මවිභංග සූත්‍රයේ එයි."),
    q("අනුන් කෙරෙහි ඉවසීමෙන් තොරව නිතර ක්‍රෝධ කිරීමෙන් ඇතිවන විපාකය කුමක්ද?", "අවලස්සන වීම (දුර්වර්ණ වීම)", "ප්‍රඥාව අඩු වීම", "දිළිඳු වීම", "රෝගී වීම", "ක්‍රෝධ නොකිරීමෙන් හා මෛත්‍රියෙන් ප්‍රසන්න රූපයක් ලැබේ."),
    q("වැඩිහිටියන්ට හා ගුණවතුන්ට ගරු නොකර මානයෙන් කටයුතු කිරීමේ විපාකය කුමක්ද?", "පහත් තත්ත්වයක ඉපදීම (නීච කුලයක)", "දිළිඳු වීම", "රෝගී වීම", "අල්පායුෂ්ක වීම", "නිහතමානී ගුණය උසස් ගෞරවනීය තත්ත්වයකට හේතු වේ."),
    q("ශ්‍රමණ බ්‍රාහ්මණයන්ගෙන් කුසල් අකුසල් විමසා ඉගෙනීමෙන් මතු භවයේ ලැබෙන විපාකය කුමක්ද?", "මහා ප්‍රඥාවන්ත වීම", "රූප සම්පත්තිය", "ධන සම්පත්තිය", "දීර්ඝායුෂ", "කුසල් අකුසල් නොවිමසීම අඥාන බවට හේතු වේ."),
    q("ලුණු කැටයක් කුඩා වතුර කෝප්පයකට හා ගංගාවකට දැමීමේ උපමාව ඇතුළත් සූත්‍රය කුමක්ද?", "ලෝණඵල සූත්‍රය", "චූලකම්මවිභංග සූත්‍රය", "කාලාම සූත්‍රය", "සීවක සූත්‍රය", "සීලය හා සමාධිය දියුණු කළ අයට කුඩා අකුසල් යටපත් වන බව මෙයින් කියවේ."),
    q("කුසල් හා අකුසල් කර්ම මරණින් පසු ඊළඟ භවය සකසන බව දැක්වෙන පුනර්භව ක්‍රියාවලිය කුමක්ද?", "පටිසන්ධි ක්‍රියාවලිය", "නිවන් මඟ", "භාවනා ක්‍රමය", "සංගායනාව", "චුති සිතට අනතුරුව කර්මය අනුව ප්‍රතිසන්ධි සිත පහළ වේ."),
    q("චිත්ත ඒකාග්‍රතාව ඇති කර ගැනීම සඳහා වඩන භාවනා ක්‍රමය හඳුන්වන්නේ කුමන නමින්ද?", "සමථ භාවනාව", "විදර්ශනා භාවනාව", "ප්‍රතිපත්ති පූජාව", "ධම්ම විචය", "කසිණ, අනුස්සති ආදී කමටහන් 40 ක් සමථ භාවනාවට අයත් වේ."),
    q("සමථ භාවනාවට අයත් මුළු කමටහන් සංඛ්‍යාව කීයද?", "හතළිහකි (40)", "තිහකි (30)", "දහයකි (10)", "විස්සකි (20)", "දස කසිණ, දස අසුභ, දස අනුස්සති ආදී කමටහන් 40 කි."),
    q("භාවනා කිරීමේදී සිතේ සමාධියට බාධා කරන 'පංච නීවරණ' යනු මොනවාද?", "කාමච්ඡන්ද, ව්‍යාපාද, ථීනමිද්ධ, උද්ධච්ච කුක්කුච්ච, විචිකිච්ඡා", "ලෝභ, ද්වේෂ, මෝහ, මාන, දිට්ඨි", "පඨවි, ආපෝ, තේජෝ, වායෝ, ආකාස", "රූප, වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ", "මෙම බාධක පහ සිතේ ප්‍රඥාව වසා දමයි."),
    q("සිතේ හා කයේ අලස බව හා නිදිමත ගතිය හඳුන්වන නීවරණය කුමක්ද?", "ථීනමිද්ධය", "උද්ධච්ච කුක්කුච්චය", "විචිකිච්ඡාව", "ව්‍යාපාදය", "ආලෝක සංඥාව හා වීර්යය වැඩීමෙන් ථීනමිද්ධය දුරු කළ හැකිය."),
    q("සිතේ නොසන්සුන් බව හා කළ වැරදි ගැන පසුතැවිලි වීම කුමන නීවරණයද?", "උද්ධච්ච කුක්කුච්චය", "කාමච්ඡන්දය", "ථීනමිද්ධය", "ව්‍යාපාදය", "සිත සංසිඳුවීමෙන් උද්ධච්ච කුක්කුච්චය දුරු වේ."),
    q("සිතේ පවතින ත්‍රිවිධ දෝෂයන්ගෙන් ව්‍යාපාදය හෙවත් තරහව දුරු කිරීමට වඩන භාවනාව කුමක්ද?", "මෛත්‍රී භාවනාව", "අසුභ භාවනාව", "මරණානුස්සතිය", "ආනාපානසතිය", "මෛත්‍රිය වැඩීමෙන් ක්‍රෝධය හා ද්වේෂය සංසිඳේ."),
    q("ආශ්වාස ප්‍රශ්වාස කෙරෙහි සිහිය පිහිටුවා වඩන භාවනාව කුමක්ද?", "ආනාපානසති භාවනාව", "බුද්ධානුස්සති භාවනාව", "මෛත්‍රී භාවනාව", "කසිණ භාවනාව", "බුදුරදුන් බුද්ධත්වයට පත්වීමේදී ද ආනාපානසති භාවනාව වැඩූ සේක."),
    q("බුදුගුණ නවය මෙනෙහි කරමින් සිත පහදා ගැනීම කුමන භාවනාවද?", "බුද්ධානුස්සති භාවනාව", "ධම්මානුස්සති භාවනාව", "සංඝානුස්සති භාවනාව", "සීලානුස්සති භාවනාව", "ඉතිපි සෝ භගවා ආදී බුදු ගුණ මෙනෙහි කිරීම බුද්ධානුස්සතියයි."),
    q("තමන් සතු කුසල ශක්තිය හා ශ්‍රද්ධාව වැඩෙන අතර කෙලෙස් යටපත් වන 'චතුරාරක්ෂක භාවනා' හතර මොනවාද?", "බුද්ධානුස්සති, මෙත්තා, අසුභ, මරණානුස්සති", "දාන, ශීල, භාවනා, පඤ්ඤා", "සද්ධා, විරිය, සති, සමාධි", "කාය, වේදනා, චිත්ත, ධම්ම", "සෑම බෞද්ධයෙකුම දිනපතා වැඩිය යුතු ආරක්ෂක භාවනා හතර මෙයයි."),
    q("ශරීරයේ අශුභ ස්වභාවය මෙනෙහි කර රාගය දුරු කිරීමට වඩන භාවනාව කුමක්ද?", "අසුභ භාවනාව (කායගතාසතිය)", "මෛත්‍රී භාවනාව", "බුද්ධානුස්සති භාවනාව", "මුදිතා භාවනාව", "දෙතිස් කුණප කොටස් මෙනෙහි කිරීමෙන් රාගය සංසිඳේ."),
    q("ජීවිතයේ අනිත්‍යතාව සිහි කරමින් ප්‍රමාදය දුරු කිරීමට වඩන භාවනාව කුමක්ද?", "මරණානුස්සති භාවනාව", "ආනාපානසති භාවනාව", "කසිණ භාවනාව", "මෛත්‍රී භාවනාව", "ඕනෑම මොහොතක මරණය සිදුවිය හැකි බව සිහි කිරීමෙන් අප්‍රමාදී වේ."),
    q("සතර සතිපට්ඨානයට අයත් ප්‍රධාන කොටස් සතර මොනවාද?", "කායානුපස්සනා, වේදනානුපස්සනා, චිත්තානුපස්සනා, ධම්මානුපස්සනා", "මෙත්තා, කරුණා, මුදිතා, උපේක්ඛා", "දාන, ප්‍රියවචන, අර්ථචර්යා, සමානාත්මතා", "ඡන්ද, චිත්ත, විරිය, වීමංසා", "සිහිය පිහිටුවන ස්ථාන සතර සතිපට්ඨාන නම් වේ."),
    q("සප්ත බොජ්ඣංග ධර්මවල පළමු අංගය කුමක්ද?", "සති සම්බොජ්ඣංගය", "ධම්මවිචය සම්බොජ්ඣංගය", "විරිය සම්බොජ්ඣංගය", "පීති සම්බොජ්ඣංගය", "සති, ධම්මවිචය, විරිය, පීති, පස්සද්ධි, සමාධි, උපෙක්ඛා සප්ත බොජ්ඣංග වේ."),
    q("සප්ත බොජ්ඣංග ධර්මවල අවසාන අංගය කුමක්ද?", "උපෙක්ඛා සම්බොජ්ඣංගය", "සමාධි සම්බොජ්ඣංගය", "පස්සද්ධි සම්බොජ්ඣංගය", "විරිය සම්බොජ්ඣංගය", "මැදහත් බව හෙවත් උපේක්ෂාව බොජ්ඣංගවල හත්වන අංගයයි."),
    q("සතර බ්‍රහ්ම විහරණ අතරින් සියලු සතුන්ගේ සැප කැමති වීම කුමන ගුණයද?", "මෙත්තා", "කරුණා", "මුදිතා", "උපේක්ඛා", "සියලු සත්වයන් කෙරෙහි මිතුරු බව මෛත්‍රියයි."),
    q("දුකට පත් සත්වයන් කෙරෙහි සිතේ ඇතිවන අනුකම්පාව හා පිහිට වීමේ කැමැත්ත කුමක්ද?", "කරුණා", "මෙත්තා", "මුදිතා", "උපේක්ඛා", "සත්වයන් දුකින් මුදා ගැනීමේ ගුණය කරුණාවයි."),
    q("අන් අයගේ දියුණුව හා සැපත දැක සතුටු වීම කුමන බ්‍රහ්ම විහරණයද?", "මුදිතා", "මෙත්තා", "කරුණා", "උපේක්ඛා", "මුදිතාව වැඩීමෙන් ඊර්ෂ්‍යාව දුරු වේ."),
    q("සැප දුක් හමුවේ මැදහත්ව කම්පා නොවී සිටීම කුමන බ්‍රහ්ම විහරණයද?", "උපේක්ඛා", "මුදිතා", "කරුණා", "මෙත්තා", "සමබර මානසිකත්වය උපේක්ෂාවයි."),
    q("මෛත්‍රී භාවනාව වැඩීමේදී පළමුවෙන්ම මෛත්‍රිය වැඩිය යුත්තේ කා කෙරෙහිද?", "තමා කෙරෙහි", "සතුරා කෙරෙහි", "මධ්‍යස්ථ පුද්ගලයා කෙරෙහි", "ප්‍රිය පුද්ගලයා කෙරෙහි", "'අහං අවේරෝ හෝමි' යැයි තමාට මෙත් වඩා අන් අයට පැතිරවිය යුතුය."),
    q("මෛත්‍රී භාවනාව වැඩීමේදී ලැබෙන ආනිසංස ගණන කීයක් බව දේශනාවේ එයිද?", "එකොළොසකි (11)", "පහකි (5)", "අටකි (8)", "හයකි (6)", "සුවසේ නිදා ගැනීම, සුවසේ අවදි වීම ආදී ආනිසංස 11ක් මෙත්තානිසංස සූත්‍රයේ එයි."),
    q("රෝගීන්ට මෙන්ම පංච නීවරණ දුරු කිරීමටත් ශ්‍රවණය කරනු ලබන පිරිත් සූත්‍රය කුමක්ද?", "බොජ්ඣංග පිරිත", "ආටානාටිය පිරිත", "ධජග්ග පිරිත", "මෝර පිරිත", "බුදුරදුන් හා මහ රහතන් වහන්සේලා බොජ්ඣංග ධර්ම මෙනෙහි කර රෝග සුව කර ගත්හ."),
    q("බෞද්ධ සමාජයේ කර්මය පිළිබඳව පවතින වැරදි මතයක් වන්නේ කුමක්ද?", "සියල්ල පූර්ව කර්මයෙන්ම සිදුවේ යැයි සිතීම", "උත්සාහයෙන් දියුණු විය හැකි බව", "චේතනාව කර්මය වන බව", "වර්තමාන ක්‍රියා වැදගත් බව", "පුබ්බේකතහේතුවාදය බුදුරදුන් විසින් ප්‍රතික්ෂේප කරන ලදී."),
    q("වර්තමාන ශිෂ්‍යයෙකු විභාගයෙන් අසමත් වීමට හේතුව පෙර කර්මයම නොවන බව පැහැදිලි වන්නේ කුමන ධර්මයෙන්ද?", "පුබ්බේකතහේතුවාදය බැහැර කිරීමෙන්", "ශාස්වතවාදයෙන්", "අහේතුකවාදයෙන්", "උච්ඡේදවාදයෙන්", "වර්තමාන උත්සාහය හා කැපවීම අනුව ප්‍රතිඵල වෙනස් කළ හැකිය."),
    q("සිතේ තැන්පත් බව හා කය සැහැල්ලු වීම දැක්වෙන බොජ්ඣංග ධර්මය කුමක්ද?", "පස්සද්ධි සම්බොජ්ඣංගය", "පීති සම්බොජ්ඣංගය", "විරිය සම්බොජ්ඣංගය", "සති සම්බොජ්ඣංගය", "නාමකාය හා රූපකාය සංසිඳීම පස්සද්ධියයි."),
    q("සක්මන් භාවනාව මගින් පුද්ගලයෙකුට ලැබෙන ප්‍රධාන ආනිසංසයක් නොවන්නේ කුමක්ද?", "අලස බව වැඩි වීම", "දීර්ඝ ගමන්වලට ඔරොත්තු දීම", "ආහාර මනාව දිරවීම", "නිරෝගී බව වැඩි වීම", "සක්මන් භාවනාවෙන් ලැබෙන සමාධිය බොහෝ කල් පවතී."),
    q("සිත කිලිටි කරන උපක්ලේශ ධර්මවලින් මිදී භාවනා කිරීමට සුදුසුම පරිසරය කුමක්ද?", "නිහඬ විවේකී පරිසරය", "ඝෝෂාකාරී වෙළඳපොළ", "ජනාකීර්ණ උත්සව බිම", "විනෝද උයන", "ශබ්ද අඩු විවේකී ස්ථාන සිතේ එකඟතාවට උපකාරී වේ."),
    q("කුසලයක හෝ අකුසලයක ප්‍රබලතාව තීරණය වන්නේ කුමක් මතද?", "චේතනාවේ ප්‍රබල බව මත", "වැය කළ මුදල මත", "ශාරීරික ප්‍රමාණය මත", "කාලගුණය මත", "පූර්ව, මුඤ්චන හා අපර චේතනා තුන පිරිසිදු වන තරමට කුසලය බලවත් වේ."),
    q("දන් දීමට පෙර සිතේ ඇතිවන සතුටුදායක චේතනාව හඳුන්වන්නේ කෙසේද?", "පූර්ව චේතනාව", "මුඤ්චන චේතනාව", "අපර චේතනාව", "අවසන් චේතනාව", "පින්කමට පෙර, කරන විට හා පසුව සතුටු වීම ත්‍රිවිධ චේතනා පාරිශුද්ධියයි."),
    q("කර්ම විපාකය වැළැක්විය නොහැකි වුවත් එහි බලපෑම අඩු කර ගත හැක්කේ කුමක් මගින්ද?", "වර්තමානයේ කුසල් හා ශීල භාවනා වැඩීමෙන්", "බලි තොවිල් කිරීමෙන්", "පලා යාමෙන්", "සොරකම් කිරීමෙන්", "කුසල් වැඩීමෙන් පෙර අකුසල්වල විපාක තීව්‍රතාව අඩු කරගත හැකිය."),
    q("පටිච්චසමුප්පාදයේ පුනර්භවය තහවුරු කරන ප්‍රධාන සාධකය කුමක්ද?", "මරණින් පසු කර්ම ශක්තිය අනුව නව විඤ්ඤාණයක් පහළ වීම", "වෙනත් ආත්මයක් ශරීරයෙන් පිටවී යාම", "සිරුර එලෙසම පැවතීම", "මව්පියන්ගෙන් පමණක් ජීවිතය ලැබීම", "ගන්ධබ්බ හෙවත් ප්‍රතිසන්ධි විඤ්ඤාණය හේතුඵල අනුව සකස් වේ."),
    q("ආනාපානසති භාවනාවේදී සිතේ සිහිය පිහිටුවිය යුතු ස්ථානය කුමක්ද?", "නාස් පුඩු අග හෝ උඩු තොල ප්‍රදේශය", "පපුව මැද", "දෙඇස් මැද", "හිස මුදුන", "හුස්ම ඇතුළු වන හා පිටවන ස්පර්ශය දැනෙන තැන සිහිය තැබිය යුතුය."),
    q("භාවනාවේ යෙදෙන විට 'පීති' හා 'සුඛ' අතර පවතින වෙනස කුමක්ද?", "පීතිය සතුටු වීම වන අතර සුඛය එම සුවය විඳීමයි", "දෙකම එකම අර්ථය දෙයි", "පීතිය දුකක් වන අතර සුඛය සැපකි", "සුඛය රූපයක් වන අතර පීතිය නාමයකි", "පීතිය සංඛාරස්කන්ධයට ද සුඛය වේදනාස්කන්ධයට ද අයත් වේ."),
    q("පංච අනන්තරිය කර්මයක් කළ පුද්ගලයෙකු මරණින් පසු අනිවාර්යයෙන්ම උපදින්නේ කොහිද?", "නිරයේ (අපායේ)", "මිනිස් ලොව", "දෙව්ලොව", "බ්‍රහ්ම ලොව", "ආනන්තරිය කර්ම වෙනත් කිසිදු කුසලයකින් යටපත් කළ නොහැකි ගරුක කර්ම වේ."),
    q("මරණාසන්නයේදී පහළ වන සිතුවිලි කාණ්ඩ තුන (කර්ම, කර්ම නිමිති, ගති නිමිති) අතරින් 'ගති නිමිති' යනු කුමක්ද?", "උපදින ඊළඟ භවයේ ස්වරූපය පෙනීම", "පෙර කළ පින් පව් මතක් වීම", "පූජා කළ මල් පහන් පෙනීම", "වෛද්‍යවරයා පෙනීම", "දෙව්ලොව විමන් හෝ නිරය ගිනි දැල් ආදිය පෙනීම ගති නිමිත්තයි."),
    q("තමන් කළ කර්මය තමාගේම දායාදය වන බව දැක්වෙන පාලි පාඨය කුමක්ද?", "කම්මස්සකා සත්තා කම්මදායාදා", "අත්තා හි අත්තනෝ නාථෝ", "ධම්මෝ හවේ රක්ඛති", "සබ්බේ සත්තා භවන්තු", "සත්වයෝ කර්මය ස්වකීය කොට හා දායාද කොට ඇත්තෝය."),
    q("සියලු අකුසල් ක්‍රියාවන් සිදුවීමට මුල් වන පොදු සාධක තුනෙන් කෝපයට මුල් වන්නේ කුමක්ද?", "ද්වේෂය", "ලෝභය", "මෝහය", "අලෝභය", "ද්වේෂය නිසා ප්‍රාණඝාතය හා පරුෂ වචන සිදු වේ."),
    q("සොරකම් කිරීමට හා අධික ඇල්මට මුල් වන අකුසල මූලය කුමක්ද?", "ලෝභය", "ද්වේෂය", "අදෝසය", "අමෝහය", "ලෝභය නිසා අදත්තාදානය හා කාමමිථ්‍යාචාරය සිදු වේ."),
    q("සිතින් වචනයෙන් කයින් පිරිසිදු වී දස කුසල් වැඩීමෙන් ලැබෙන උසස්ම ප්‍රතිඵලය කුමක්ද?", "සසර සැප හා නිවනට මඟ සැලසීම", "අනුන්ගේ ප්‍රශංසාව පමණක්", "නොමැරී සිටීම", "ධනය වැඩිවීම පමණක්", "කුසලය දුගතියෙන් මුදා සුගතියට හා විමුක්තියට මඟ පාදයි."),
    q("කර්මයට අනුව සත්වයා විවිධ ස්වරූපවලින් උපදින බව විස්තර කළ සූත්‍රය කුමක්ද?", "කුක්කුරවතික සූත්‍රය", "රතන සූත්‍රය", "මංගල සූත්‍රය", "ධම්මචක්ක සූත්‍රය", "කළු-සුදු කර්ම සතර ආකාරයකින් බෙදා කුක්කුරවතික සූත්‍රයේ විස්තර කෙරේ."),
    q("විපාක නොදෙන ලෝකෝත්තර කර්මය ලෙස කුක්කුරවතික සූත්‍රයේ දැක්වෙන්නේ කුමක්ද?", "අකණ්හ අසුක්ක කම්මය (කළුත් නොවන සුදුත් නොවන)", "කණ්හ කම්මය", "සුක්ක කම්මය", "කණ්හසුක්ක කම්මය", "කර්ම ක්ෂය කරන ආර්ය අෂ්ටාංගික මාර්ගය අකණ්හ අසුක්ක කර්මයයි."),
    q("මිශ්‍ර කුසලාකුසල කර්ම (කණ්හසුක්ක කම්ම) හේතුවෙන් උපදින්නේ කුමන ලෝකයේද?", "මනුෂ්‍ය ලෝකයේ", "නිරයේ", "බ්‍රහ්ම ලෝකයේ", "අසුර ලෝකයේ", "සැප දුක් මිශ්‍රව විඳින මිනිස් ලොව කණ්හසුක්ක කර්ම විපාකයකි."),
    q("සිතේ අවිචාරවත් බව හා නොදැනුවත්කම හේතුවෙන් ඇතිවන අකුසල මූලය කුමක්ද?", "මෝහය", "ලෝභය", "ද්වේෂය", "මානය", "සියලු අකුසල්වලට මුල් වන මුළාව මෝහයයි."),
    q("මනසේ ස්වභාවය 'පභස්සර' (ප්‍රභාස්වර) වුවත් එය කිලිටි වන්නේ කුමක් නිසාද?", "ආගන්තුක උපක්ලේශ නිසා", "භාවනා කිරීම නිසා", "පිරිත් ඇසීම නිසා", "ශීලය රැකීම නිසා", "පිටතින් එන රාගාදී කෙලෙස් සිත කිලිටි කරයි."),
    q("ආර්ය පුද්ගලයෙකුගේ සිතේ පවතින භාවනාමය සමාධියෙන් ලැබෙන විශේෂ ලක්ෂණය කුමක්ද?", "නොසැලෙන නිශ්චල බව හා පැහැදිලි බව", "වේගයෙන් වෙනස් වීම", "බිය ගැනීම", "කෝප වීම", "සමාහිත සිත පැහැදිලි ජල තටාකයක් මෙන් යථාර්ථය පෙන්වයි."),
    q("විදර්ශනා භාවනාව වැඩීම සඳහා මූලිකවම අවශ්‍ය වන පදනම කුමක්ද?", "සීල විසුද්ධිය", "ධන සම්පත්තිය", "උසස් රැකියාව", "බලවත් ශරීරය", "ශීලයෙන් තොරව චිත්ත සමාධිය හා ප්‍රඥාව ගොඩනැගිය නොහැකිය."),
    q("ධම්මවිචය සම්බොජ්ඣංගය යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ධර්මය නුවණින් විමසා බැලීම", "සිහියෙන් සිටීම", "සතුටු වීම", "නිහඬව සිටීම", "කුසල් අකුසල් හා ත්‍රිලක්ෂණය විමසා බැලීම ධම්මවිචයයි."),
    q("සතිපට්ඨාන භාවනාවේදී 'වේදනානුපස්සනාව' යටතේ නිරීක්ෂණය කරන්නේ කුමක්ද?", "සැප, දුක් හා උපේක්ෂා වේදනාවන්ගේ ඇතිවීම හා නැතිවීම", "හුස්ම ගැනීම පමණක්", "පංච නීවරණ පමණක්", "කෙස් ලොම් ආදිය", "සියලු විඳීම් අනිත්‍ය ලෙස නුවණින් දැකීම වේදනානුපස්සනාවයි."),
    q("බෞද්ධ ඉගැන්වීම් අනුව පුනර්භවය පිළිගැනීමෙන් සමාජයට සිදුවන යහපත කුමක්ද?", "වැරදි ක්‍රියාවලින් වැළකී වගකීමෙන් කටයුතු කිරීම", "අලසව කාලය ගෙවීම", "අනුන්ට හිංසා කිරීම", "පූජාවලට පමණක් සීමා වීම", "තම ක්‍රියාවන්ට තමා වගකිව යුතු බව වැටහීමෙන් සදාචාරය දියුණු වේ."),
    q("නිදා ගැනීමේදී පවා සිහියෙන් යුතුව සිටීමට උගන්වන පිළිවෙත කුමක්ද?", "ජාගරියානුයෝගය", "ආහාරයේ මත්තඤ්ඤුතාව", "ඉන්ද්‍රිය සංවරය", "සති සම්පජඤ්ඤය", "නිදිමත දුරු කරමින් නිසි වේලාවට පමණක් නින්ද ලබා කුසල් වැඩීමයි."),
    q("කිසියම් දෙයක් කිරීමට පෙර එහි යෝග්‍ය අයෝග්‍ය බව විමසීම කුමන ධර්මයද?", "සම්පජඤ්ඤය (මනා නුවණ)", "මෝහය", "ප්‍රමාදය", "විචිකිච්ඡාව", "සත්ථක, සප්පාය, ගෝචර, අසම්මෝහ යනු සතර සම්පජඤ්ඤයයි."),
    q("බුදුරදුන් 'ධම්මෝ පදීපෝ' යනුවෙන් ධර්මය පහනකට උපමා කළේ ඇයි?", "අවිද්‍යා අන්ධකාරය දුරු කරන බැවින්", "තාපය ලබා දෙන බැවින්", "දැවී අවසන් වන බැවින්", "රාත්‍රියට පමණක් වැදගත් බැවින්", "ධර්මය මිනිසාට ජීවිතයේ නිවැරදි මාර්ගය ආලෝකවත් කර දෙයි."),
    q("වයස්ගත වුවත් නොසැලෙන උත්සාහයෙන් චිත්ත ඒකාග්‍රතාව රැක ගැනීමට උපකාරී වන බලය කුමක්ද?", "විරිය බලය", "සද්ධා බලය", "සති බලය", "පඤ්ඤා බලය", "පසුබට නොවන වීර්යය භාවනා සාර්ථකත්වයට අත්‍යවශ්‍ය වේ."),
    q("බෞද්ධ සමාජයේ සිදු කරන 'අටපිරිකර පූජාව' කුමන ආකාරයේ පුණ්‍ය කර්මයක්ද?", "දානමය පුණ්‍ය කර්මයකි", "භාවනාමය පුණ්‍ය කර්මයකි", "වෙය්‍යාවච්ච පුණ්‍ය කර්මයකි", "දිට්ඨිජුකම්ම පුණ්‍ය කර්මයකි", "භික්ෂූන්ට අවශ්‍ය අත්‍යවශ්‍ය පිරිකර දීම ආමිස දානයකි."),
    q("කෙනෙකු තමා කළ පව් ගැන පසුතැවිලි නොවී ඒවා නැවත නොකිරීමට අධිෂ්ඨාන කිරීම හඳුන්වන්නේ කෙසේද?", "සංවරයෙහි පිහිටීම", "විනාශය", "උද්ධච්චය", "අභිමානය", "පාපයෙන් වෙන්වී කුසල් මගට අවතීර්ණ වීම බුදුදහම අගය කරයි."),
    q("භාවනාමය කුසලය අනෙක් දාන හා ශීල කුසලවලට වඩා ශ්‍රේෂ්ඨ වන්නේ ඇයි?", "සිතේ කෙලෙස් මුලින්ම දුරු කිරීමට මඟ පාදන බැවින්", "වියදමක් නැති නිසා පමණක්", "කාලය ගත වන නිසා", "වැඩි පිරිසක් බලා සිටින නිසා", "විදර්ශනා භාවනාවෙන් නිවන් මඟ සෘජුවම විවෘත වේ.")
  )
}
